                OffsetDateTime.ofInstant(leg.loadingCutoff(), ZoneOffset.UTC),
                OffsetDateTime.ofInstant(now, ZoneOffset.UTC), request.requestId());
        insertEvent(bag.bagTag(), EVT_LOADED, legId, leg.origin());
    }
